def normalize_alarm_label(value):
    return " ".join("".join(ch.lower() if ch.isalnum() else " " for ch in str(value)).split())

def wake_label_rank(alarm):
    normalized = normalize_alarm_label(alarm.get("label", ""))
    compact = normalized.replace(" ", "")
    if normalized in {"wake up", "wake up alarm", "wake alarm"}:
        return 0
    if "wake up" in normalized or "wakeup" in compact:
        return 1
    if "wake" in normalized.split():
        return 2
    return None

ranked_wake_candidates = []
for alarm in initial_alarms:
    candidate_rank = wake_label_rank(alarm)
    if candidate_rank is not None:
        ranked_wake_candidates.append((candidate_rank, alarm))
print({"wake_candidates": [{"alarm_id": alarm["alarm_id"], "label": alarm["label"], "time": alarm["time"], "rank": rank} for rank, alarm in ranked_wake_candidates]})
if not ranked_wake_candidates:
    raise RuntimeError("No alarm label identifies a wake-up alarm")
best_wake_rank = min(rank for rank, alarm in ranked_wake_candidates)
best_wake_candidates = [alarm for rank, alarm in ranked_wake_candidates if rank == best_wake_rank]
if len(best_wake_candidates) != 1:
    raise RuntimeError("The wake-up alarm is ambiguous")
target_before = best_wake_candidates[0]
target_alarm_id = target_before["alarm_id"]
time_parts = target_before["time"].split(":")
if len(time_parts) != 2:
    raise RuntimeError("The wake-up alarm time is not in HH:MM format")
original_minutes = int(time_parts[0]) * 60 + int(time_parts[1])
new_minutes = (original_minutes - 40) % (24 * 60)
new_wake_time = f"{new_minutes // 60:02d}:{new_minutes % 60:02d}"
print({"target_alarm_id": target_alarm_id, "original_time": target_before["time"], "new_time": new_wake_time})

